"use client";

import { use } from "react";
import { getBlogBySlug } from "@/data/blogs";
import { ArrowLeft, Share2, Facebook, Twitter, Linkedin, MessageSquare } from "lucide-react";
import Link from "next/link";
import { cn } from "@/lib/utils";
import FinalCTA from "@/components/sections/FinalCTA";

export default function BlogDetail({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = use(params);
  const blog = getBlogBySlug(slug);

  if (!blog) return <div>Article not found</div>;

  return (
    <div className="pt-32 pb-24">
      {/* Article Header */}
      <section className="px-6 mb-20">
        <div className="max-w-4xl mx-auto">
          <Link href="/blogs" className="inline-flex items-center gap-2 text-white/40 hover:text-primary transition-colors mb-12 group">
            <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
            Back to Blog
          </Link>
          
          <div className="space-y-6">
            <div className="px-4 py-1.5 bg-primary/10 border border-primary/20 rounded-full text-[10px] uppercase tracking-widest text-primary font-bold w-fit">
              {blog.category}
            </div>
            <h1 className="text-4xl md:text-6xl font-black text-white leading-tight font-outfit">
              {blog.title}
            </h1>
            <div className="flex flex-wrap items-center gap-6 pt-6 border-t border-white/5">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-gradient-to-br from-primary to-accent rounded-full flex items-center justify-center font-bold text-white">
                  W
                </div>
                <div>
                  <p className="text-white font-bold text-sm">{blog.author}</p>
                  <p className="text-white/30 text-[10px]">{blog.date} • {blog.readTime}</p>
                </div>
              </div>
              <div className="flex items-center gap-4 ml-auto">
                <button className="p-2 bg-white/5 rounded-full hover:bg-white/10 text-white/40 hover:text-white transition-all">
                  <Twitter className="w-4 h-4" />
                </button>
                <button className="p-2 bg-white/5 rounded-full hover:bg-white/10 text-white/40 hover:text-white transition-all">
                  <Linkedin className="w-4 h-4" />
                </button>
                <button className="p-2 bg-white/5 rounded-full hover:bg-white/10 text-white/40 hover:text-white transition-all">
                  <Share2 className="w-4 h-4" />
                </button>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Article Content */}
      <article className="px-6 mb-32">
        <div className="max-w-3xl mx-auto">
          <div className="prose prose-invert prose-lg max-w-none text-foreground/70 leading-relaxed space-y-8">
            <p className="text-xl text-white/90 font-medium leading-relaxed italic border-l-4 border-primary pl-8 py-2">
              {blog.excerpt}
            </p>
            
            <p>
              {blog.content}
            </p>

            <h3 className="text-2xl font-bold text-white font-outfit pt-8">The Core Principles</h3>
            <p>
              In our experience building dozens of high-performance applications, we've found that performance isn't something you can sprinkle on at the end. It's a fundamental architectural decision.
            </p>
            
            <div className="glass p-8 rounded-3xl border-primary/20 my-12">
              <h4 className="text-xl font-bold text-white mb-4 font-outfit">Key Takeaways</h4>
              <ul className="space-y-4 text-base">
                <li className="flex gap-4">
                  <div className="w-2 h-2 bg-primary rounded-full mt-2 shrink-0" />
                  <span>Always prioritize server-side rendering for critical data.</span>
                </li>
                <li className="flex gap-4">
                  <div className="w-2 h-2 bg-primary rounded-full mt-2 shrink-0" />
                  <span>Optimize images and assets using modern compression.</span>
                </li>
                <li className="flex gap-4">
                  <div className="w-2 h-2 bg-primary rounded-full mt-2 shrink-0" />
                  <span>Use GSAP for performance-safe animations that don't jank.</span>
                </li>
              </ul>
            </div>

            <p>
              We believe that the future of the web belongs to those who prioritize the user's experience across all devices and connection speeds.
            </p>
          </div>

          <div className="mt-20 pt-12 border-t border-white/5">
            <div className="flex flex-col md:flex-row items-center justify-between gap-8 glass p-10 rounded-[3rem] border-primary/20">
              <div className="max-w-md">
                <h4 className="text-2xl font-bold text-white mb-2 font-outfit">Want more insights?</h4>
                <p className="text-foreground/60 text-sm">
                  Subscribe to our collective newsletter to get the latest engineering and design strategy delivered to your inbox.
                </p>
              </div>
              <div className="flex w-full md:w-auto gap-4">
                <input 
                  type="email" 
                  placeholder="name@email.com"
                  className="bg-black/40 border border-white/10 rounded-xl px-6 py-4 text-white text-sm outline-none focus:border-primary transition-colors flex-grow md:w-64"
                />
                <button className="bg-primary text-white font-bold py-4 px-8 rounded-xl hover:scale-105 transition-transform shrink-0">
                  Join
                </button>
              </div>
            </div>
          </div>
        </div>
      </article>

      <FinalCTA />
    </div>
  );
}
